#!/usr/bin/env python3
from __future__ import annotations
import base64, gzip, subprocess, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXPECTED = "0.10.768"
TARGET = "0.10.769"
PATCH_B64 = ""

def run(*args):
    subprocess.run(args, cwd=ROOT, check=True)

def main():
    version = (ROOT / "VERSION").read_text(encoding="utf-8").strip()
    if version == TARGET:
        print(f"already applied: {TARGET}")
        return 0
    if version != EXPECTED:
        print(f"refusing to apply: VERSION={version}, expected {EXPECTED}", file=sys.stderr)
        return 2
    patch = gzip.decompress(base64.b64decode(PATCH_B64))
    patch_path = ROOT / ".v769.patch.tmp"
    patch_path.write_bytes(patch)
    try:
        run("git", "apply", "--check", str(patch_path))
        run("git", "apply", str(patch_path))
    finally:
        patch_path.unlink(missing_ok=True)
    print(f"applied {EXPECTED} -> {TARGET}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
